<script setup lang="ts">
import { ref } from 'vue'
import { useRoute, useRouter } from 'vue-router'
import { useSession } from '../stores/session'
import { api, type Profile } from '../api/client'
import BrandMark from '../components/BrandMark.vue'
import FeedbackBox from '../components/FeedbackBox.vue'
const session = useSession(), route = useRoute(), router = useRouter()
const name = ref(session.user?.name || ''), currentPassword = ref(''), password = ref(''), busy = ref(false), error = ref(''), success = ref('')
async function save() { busy.value = true; error.value = ''; success.value = ''; try { if (route.path === '/app/settings') { await api('/me/password','POST',{ currentPassword: currentPassword.value, password: password.value }); session.user = null; await router.push('/login') } else { session.user = await api<Profile>('/me','PATCH',{ name: name.value }); success.value = 'Profile saved.' } } catch (e) { error.value = e instanceof Error ? e.message : 'Unable to save.' } finally { busy.value = false } }
async function logout() { try { await session.logout(); await router.push('/login') } catch (e) { error.value = String(e) } }
</script>
<template><div class="customer-page"><header class="public-nav"><BrandMark /><nav><RouterLink to="/app">Overview</RouterLink><RouterLink to="/app/profile">Profile</RouterLink><RouterLink to="/app/settings">Security</RouterLink><button class="secondary" @click="logout">Sign out</button></nav></header><main class="customer-main"><span class="eyebrow">YOUR WORKSPACE</span><h1>{{ route.path === '/app' ? `Welcome, ${session.user?.name}.` : route.path === '/app/profile' ? 'Your profile.' : 'Account security.' }}</h1><FeedbackBox :error="error" :success="success" /><template v-if="route.path === '/app'"><p class="lead">A good place to begin your next shipping journey.</p><div class="feature-grid"><article class="panel"><span class="eyebrow">ACCOUNT</span><h3>{{ session.user?.name }}</h3><p>{{ session.user?.email }}</p><span class="badge">{{ session.user?.status }}</span><p>Email verification complete</p></article><article class="panel"><span class="eyebrow">COMING IN A FUTURE PHASE</span><h3>Your next shipment starts here.</h3><p>Carrier comparison and booking are not available yet.</p><button disabled>Compare shipping options</button></article></div></template><form v-else class="panel narrow" @submit.prevent="save"><template v-if="route.path === '/app/profile'"><label>Email address<input :value="session.user?.email" disabled></label><label>Full name<input v-model="name" required minlength="2" maxlength="100"></label></template><template v-else><label>Current password<input v-model="currentPassword" type="password" required autocomplete="current-password"></label><label>New password<input v-model="password" type="password" required minlength="12" maxlength="128" autocomplete="new-password"></label><p class="fine">Changing your password signs out all existing sessions.</p></template><button :disabled="busy">{{ busy ? 'Saving…' : 'Save changes' }}</button></form></main></div></template>